(() => {
  'use strict';
  const FAV_KEY = 'snu-lab-favorites-v1';
  const COMPARE_MAX = 4;
  let compare = new Set();
  const getUnits = () => [...(window.RESEARCH_UNITS || []), ...(window.RESEARCH_UNIT_SUPPLEMENTS || [])];
  const getUnit = id => getUnits().find(x => String(x.id) === String(id));
  const getSaved = () => { try { return new Set(JSON.parse(localStorage.getItem(FAV_KEY) || '[]')); } catch (_) { return new Set(); } };
  const save = s => localStorage.setItem(FAV_KEY, JSON.stringify([...s]));
  const escapeHtml = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const enrichment = id => (window.PRECOMPUTED_ENRICHMENT || {})[id] || {};
  const activity = id => (window.RESEARCH_ACTIVITY || {})[id] || {};
  const papers = id => { const e=enrichment(id), a=activity(id); return (Array.isArray(e.recent_papers)&&e.recent_papers.length?e.recent_papers:(a.papers||[])).filter(Boolean).slice(0,10); };
  const keywords = id => [...new Set([...(enrichment(id).recommendation_keywords||[]), ...(enrichment(id).research_topics||[]), ...String(getUnit(id)?.keywords||'').split(/[;,|]/)].map(x=>String(x).trim()).filter(Boolean))].slice(0,8);
  const trend = id => { const y={}; papers(id).forEach(p=>{const m=String(p.year||'').match(/20\d{2}/); if(m)y[m[0]]=(y[m[0]]||0)+1;}); return Object.entries(y).sort((a,b)=>b[0].localeCompare(a[0])).map(([k,v])=>`${k} ${v}편`).join(' · ')||'연도 확인 전'; };
  const roleCounts = id => { const e=enrichment(id), a=activity(id), c={박사:0,석사:0,학부:0,동문:0}; (e.current_members||[]).forEach(p=>{const r=String(p.role||'').toLowerCase(); if(/ph\.?d|박사/.test(r))c.박사++; else if(/master|석사/.test(r))c.석사++; else if(/undergraduate|학부/.test(r))c.학부++;}); if(!e.current_members?.length&&a.members){Object.entries(a.members).forEach(([g,n])=>{const r=String(g).toLowerCase(); if(/ph\.?d|박사/.test(r))c.박사+=n.length; else if(/master|석사/.test(r))c.석사+=n.length; else if(/undergraduate|학부/.test(r))c.학부+=n.length;});} c.동문=(e.alumni||[]).length; return c; };
  const css = document.createElement('style'); css.textContent = `.fav-compare-tools{display:flex;gap:6px;margin-left:auto;flex:0 0 auto}.fav-compare-tool{border:1px solid #d8e3ef;background:#fff;color:#2d5377;border-radius:9px;min-width:34px;height:32px;font-size:17px;cursor:pointer}.fav-compare-tool.active{background:#f3ecff;color:#6b43c6;border-color:#cbb9ef}.fav-panel{margin:12px 0;padding:12px 14px;border:1px solid var(--line,#d9e4ef);border-radius:14px;background:#f8fbff;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.fav-panel strong{color:#135fbe}.fav-panel button{border:0;border-radius:9px;padding:8px 11px;background:#135fbe;color:white;font-weight:800;cursor:pointer}.fav-panel button.secondary{background:white;color:#135fbe;border:1px solid #c7d7e8}.fav-dialog{width:min(1050px,calc(100% - 28px));max-height:88vh;border:0;border-radius:18px;padding:24px}.fav-dialog table{width:100%;border-collapse:collapse;font-size:.8rem}.fav-dialog th,.fav-dialog td{border-bottom:1px solid #e1e9f1;padding:10px;vertical-align:top;text-align:left}.fav-dialog small{display:block;color:#6b7f93;font-weight:500;margin-top:3px}.fav-overall{padding:10px 12px;margin:12px 0;border-radius:10px;background:#f3efff;color:#4e3b82;font-size:.82rem}`; document.head.appendChild(css);

  function injectPanel(){
    if(document.querySelector('#favComparePanel'))return;
    const panel=document.createElement('div'); panel.id='favComparePanel'; panel.className='fav-panel'; panel.innerHTML='<strong>즐겨찾기</strong><span id="favCount">0개</span><button id="favShow" type="button">즐겨찾기 보기</button><span id="cmpCount">0개 선택</span><button id="cmpOpen" type="button">선택 연구실 비교</button><button id="cmpClear" class="secondary" type="button">비교 선택 해제</button>';
    const target=document.querySelector('.summary')||document.querySelector('.search'); target?.after(panel);
    document.querySelector('#favShow').onclick=showFavorites;
    document.querySelector('#cmpOpen').onclick=showCompare;
    document.querySelector('#cmpClear').onclick=()=>{compare.clear();decorateCards();};
    refreshPanel();
  }
  function refreshPanel(){ const s=getSaved(); document.querySelector('#favCount')?.replaceChildren(document.createTextNode(`${s.size}개`)); document.querySelector('#cmpCount')?.replaceChildren(document.createTextNode(`${compare.size}개 선택`)); const btn=document.querySelector('#cmpOpen'); if(btn)btn.disabled=compare.size<2; }
  function decorateCards(){
    injectPanel(); const saved=getSaved();
    document.querySelectorAll('#results .card').forEach(card=>{ const i=Number(card.dataset.i); const unit=getUnits()[i]; if(!unit)return; let tools=card.querySelector('.fav-compare-tools'); if(!tools){tools=document.createElement('span');tools.className='fav-compare-tools';card.appendChild(tools);} const f=saved.has(unit.id), c=compare.has(unit.id); tools.innerHTML=`<button class="fav-compare-tool ${f?'active':''}" type="button" title="즐겨찾기">${f?'★':'☆'}</button><button class="fav-compare-tool ${c?'active':''}" type="button" title="비교 선택">${c?'✓':'＋'}</button>`; tools.querySelector('button').onclick=e=>{e.stopPropagation();const x=getSaved();f?x.delete(unit.id):x.add(unit.id);save(x);decorateCards();}; tools.querySelectorAll('button')[1].onclick=e=>{e.stopPropagation();if(c)compare.delete(unit.id);else if(compare.size<COMPARE_MAX)compare.add(unit.id);else return;decorateCards();}; }); refreshPanel(); }
  function observe(){ const r=document.querySelector('#results'); if(!r)return; new MutationObserver(decorateCards).observe(r,{childList:true}); decorateCards(); }
  function showFavorites(){ const s=[...getSaved()].map(getUnit).filter(Boolean); const d=document.querySelector('#favDialog')||document.body.appendChild(Object.assign(document.createElement('dialog'),{id:'favDialog',className:'fav-dialog'})); d.innerHTML=`<button type="button" class="fav-close">×</button><h2>즐겨찾기</h2>${s.length?'<table><thead><tr><th>교수</th><th>연구실</th><th>핵심 키워드</th><th>최근 논문 흐름</th></tr></thead><tbody>'+s.map(u=>`<tr><th>${escapeHtml(u.name)}</th><td>${escapeHtml(u.labs||u.title||'연구그룹')}</td><td>${escapeHtml(keywords(u.id).join(' · ')||'확인 전')}</td><td>${escapeHtml(trend(u.id))}</td></tr>`).join('')+'</tbody></table>':'<p>저장된 연구실이 없습니다.</p>'}`; d.querySelector('.fav-close').onclick=()=>d.close(); if(!d.open)d.showModal(); }
  function showCompare(){ if(compare.size<2)return; const items=[...compare].map(getUnit).filter(Boolean).slice(0,COMPARE_MAX); const d=document.querySelector('#compareDialog')||document.body.appendChild(Object.assign(document.createElement('dialog'),{id:'compareDialog',className:'fav-dialog'})); d.innerHTML=`<button type="button" class="fav-close">×</button><h2>연구실 비교</h2><p>저장된 AI 요약·키워드와 최근 논문 연도 정보를 이용한 간결 비교입니다.</p><table><thead><tr><th>항목</th>${items.map(u=>`<th>${escapeHtml(u.name)}<small>${escapeHtml(u.labs||u.title||'연구그룹')}</small></th>`).join('')}</tr></thead><tbody><tr><th>핵심 분야</th>${items.map(u=>`<td>${escapeHtml((enrichment(u.id).research_summary||u.fields||'').slice(0,220))}</td>`).join('')}</tr><tr><th>키워드</th>${items.map(u=>`<td>${escapeHtml(keywords(u.id).join(' · ')||'확인 전')}</td>`).join('')}</tr><tr><th>최근 논문 흐름</th>${items.map(u=>`<td>${escapeHtml(trend(u.id))}</td>`).join('')}</tr><tr><th>구성원</th>${items.map(u=>{const c=roleCounts(u.id);return `<td>${c.박사?`박사 ${c.박사}`:''}${c.석사?` · 석사 ${c.석사}`:''}${c.학부?` · 학부 ${c.학부}`:''}${c.동문?` · 동문 ${c.동문}`:''}</td>`;}).join('')}</tr><tr><th>모집</th>${items.map(u=>`<td>${escapeHtml(enrichment(u.id).recruitment_summary||'확인 전')}</td>`).join('')}</tr></tbody></table><div id="compareAiBox"><button id="compareAiRun" type="button">Gemini로 핵심 차이만 정리</button></div>`; d.querySelector('.fav-close').onclick=()=>d.close(); d.querySelector('#compareAiRun').onclick=()=>compactAiCompare(items,d); if(!d.open)d.showModal(); }
  async function compactAiCompare(items,d){ const box=d.querySelector('#compareAiBox'); const key=sessionStorage.getItem('snu-lab-gemini-key')||''; if(!key){box.innerHTML='<p>Gemini 키가 연결된 경우에만 AI 차이 요약을 실행할 수 있습니다.</p>';return;} box.innerHTML='<p>AI 비교 중…</p>'; try { const response=await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent',{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({contents:[{role:'user',parts:[{text:JSON.stringify({task:'Compare these labs in concise Korean. Use only supplied data. Focus on differences and recent paper trend. Return 1 sentence overall and one short phrase per lab.',labs:items.map(u=>({id:u.id,name:u.name,summary:(enrichment(u.id).research_summary||u.fields||'').slice(0,300),keywords:keywords(u.id),papers:papers(u.id).map(p=>({title:p.title,year:p.year}))}))})}]}],generationConfig:{temperature:.1,maxOutputTokens:900,responseMimeType:'application/json',responseSchema:{type:'OBJECT',properties:{overall:{type:'STRING'},rows:{type:'ARRAY',items:{type:'OBJECT',properties:{id:{type:'STRING'},difference:{type:'STRING'}},required:['id','difference']}}},required:['overall','rows']}}})}); if(!response.ok)throw new Error(`Gemini API ${response.status}`); const data=await response.json(); const txt=data?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'{}'; const r=JSON.parse(txt.replace(/^```json\s*/i,'').replace(/\s*```$/,'')); box.innerHTML=`<div class="fav-overall">${escapeHtml(r.overall||'')}</div><table><tbody>${(r.rows||[]).filter(x=>items.some(u=>u.id===x.id)).map(x=>`<tr><th>${escapeHtml(getUnit(x.id)?.name||x.id)}</th><td>${escapeHtml(String(x.difference||'').slice(0,180))}</td></tr>`).join('')}</tbody></table>`; } catch(e){box.innerHTML=`<p>${escapeHtml(e.message)}</p>`;} }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observe);else observe();
})();
